131:   private static class ChainIndex implements Iterator<Handler> {
132:     final Handler[] handlers;
133:     Registry registry;
134:     final boolean first;
135:     int i;
136: 
137:     private ChainIndex(Handler[] handlers, Registry registry, boolean first) {
138:       this.handlers = handlers;
139:       this.registry = registry;
140:       this.first = first;
141:     }
142: 
143:     public Handler next() {
144:       return handlers[i++];
145:     }
