157:   public static void start(EventLoop eventLoop, final RequestConstants requestConstants, Registry registry, Handler[] handlers, Action<? super Execution> onComplete) {
158:     ChainIndex index = new ChainIndex(handlers, registry, true);
159:     requestConstants.indexes.push(index);
160: 
161:     DefaultContext context = new DefaultContext(requestConstants);
162:     requestConstants.context = context;
163: 
164:     context.pathBindings = new PathBindingStorage(new RootPathBinding(requestConstants.request.getPath()));
165: 
166:     requestConstants.applicationConstants.execController.fork()
167:       .onError(throwable -> requestConstants.context.error(throwable instanceof HandlerException ? throwable.getCause() : throwable))
168:       .onComplete(onComplete)
169:       .register(s -> s
170:         .add(Context.TYPE, context)
171:         .add(Request.TYPE, requestConstants.request)
172:         .add(Response.TYPE, requestConstants.response)
173:         .add(PathBindingStorage.TYPE, context.pathBindings)
174:         .addLazy(RequestId.TYPE, () -> registry.get(RequestId.Generator.TYPE).generate(requestConstants.request))
175:       )
176:       .eventLoop(eventLoop)
177:       .onStart(e -> DefaultRequest.setDelegateRegistry(requestConstants.request, e))
178:       .start(e -> {
179:         requestConstants.execution = e;
180:         context.joinedRegistry = new ContextRegistry(context).join(requestConstants.execution);
181:         context.next();
182:       });
183:   }
