318:   public <T, O> T parse(TypedData body, Parse<T, O> parse) throws Exception {
319:     Function<Parser<?>, T> parserPredicate;
320:     List<Parser<?>> parsers = Lists.newArrayList();
321:     if (parse.getOpts().isPresent()) {
322:       parserPredicate = parser -> {
323:         if (parser.getOptsType().isInstance(parse.getOpts().get())) {
324:           parsers.add(parser);
325:           Parser<O> cast = Types.cast(parser);
326:           return cast.parse(DefaultContext.this, body, parse);
327:         }
328:         return null;
329:       };
330:     } else {
331:       parserPredicate = parser -> {
332:         parsers.add(parser);
333:         Parser<O> cast = Types.cast(parser);
334:         return cast.parse(DefaultContext.this, body, parse);
335:       };
336:     }
