338:     return joinedRegistry
339:       .first(PARSER_TYPE_TOKEN, parserPredicate)
340:       .orElseThrow(() -> new NoSuchParserException(parse.getType(), parse.getOpts().orElse(null), body.getContentType().getType(), parsers));
