417:   private void onErrorHandlerError(ServerErrorHandler serverErrorHandler, Throwable original, Throwable errorHandlerThrowable) {
418:     String msg = "Throwable thrown by error handler " + serverErrorHandler + " while handling throwable\n"
419:       + "Original throwable: " + getStackTraceAsString(original) + "\n"
420:       + "Error handler throwable: " + getStackTraceAsString(errorHandlerThrowable);
421: 
422:     LOGGER.error(msg);
423: 
424:     Response response = requestConstants.response.status(500);
425:     if (getServerConfig().isDevelopment()) {
426:       response.send(msg);
427:     } else {
428:       response.send();
429:     }
430:   }
