381:   public void lastModified(Instant lastModified, Runnable runnable) {
382:     Instant ifModifiedSince = requestConstants.request.getHeaders().getInstant(IF_MODIFIED_SINCE);
383: 
384:     if (ifModifiedSince != null) {
385:       // Normalise to second resolution
386:       ifModifiedSince = Instant.ofEpochSecond(ifModifiedSince.getEpochSecond());
387:       lastModified = Instant.ofEpochSecond(lastModified.getEpochSecond());
388: 
389:       if (!lastModified.isAfter(ifModifiedSince)) {
390:         requestConstants.response.status(Status.NOT_MODIFIED).send();
391:         return;
392:       }
393:     }
394: 
395:     requestConstants.response.getHeaders().setDate(HttpHeaderConstants.LAST_MODIFIED, lastModified);
396:     runnable.run();
