399:   public void error(Throwable throwable) {
400:     ServerErrorHandler serverErrorHandler = get(ServerErrorHandler.TYPE);
401:     throwable = unpackThrowable(throwable);
402: 
403:     ThrowableHolder throwableHolder = getRequest().maybeGet(ThrowableHolder.TYPE).orElse(null);
404:     if (throwableHolder == null) {
405:       getRequest().add(ThrowableHolder.TYPE, new ThrowableHolder(throwable));
406: 
407:       try {
408:         serverErrorHandler.error(this, throwable);
409:       } catch (Throwable errorHandlerThrowable) {
410:         onErrorHandlerError(serverErrorHandler, throwable, errorHandlerThrowable);
411:       }
412:     } else {
413:       onErrorHandlerError(serverErrorHandler, throwableHolder.getThrowable(), throwable);
414:     }
415:   }
416: 
417:   private void onErrorHandlerError(ServerErrorHandler serverErrorHandler, Throwable original, Throwable errorHandlerThrowable) {
418:     String msg = "Throwable thrown by error handler " + serverErrorHandler + " while handling throwable\n"
419:       + "Original throwable: " + getStackTraceAsString(original) + "\n"
420:       + "Error handler throwable: " + getStackTraceAsString(errorHandlerThrowable);
421: 
422:     LOGGER.error(msg);
423: 
424:     Response response = requestConstants.response.status(500);
425:     if (getServerConfig().isDevelopment()) {
426:       response.send(msg);
427:     } else {
428:       response.send();
429:     }
430:   }
